### LoginForm.tsx
```tsx
import React, { useState } from 'react';
import { mockUser } from '../mockData';

interface LoginFormProps {
  onSubmit: (email: string, password: string) => void;
}

export default function LoginForm({ onSubmit }: LoginFormProps) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [emailError, setEmailError] = useState('');
  const [passwordError, setPasswordError] = useState('');
  const [isPasswordVisible, setIsPasswordVisible] = useState(false);

  const validateEmail = (email: string): boolean => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  };

  const validatePassword = (password: string): boolean => {
    return password.length >= 6;
  };

  const handleEmailChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setEmail(e.target.value);
    if (emailError) setEmailError('');
  };

  const handlePasswordChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setPassword(e.target.value);
    if (passwordError) setPasswordError('');
  };

  const togglePasswordVisibility = () => {
    setIsPasswordVisible(!isPasswordVisible);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newEmailError = !validateEmail(email) ? 'Invalid email address' : '';
    const newPasswordError = !validatePassword(password) ? 'Password must be at least 6 characters' : '';
    setEmailError(newEmailError);
    setPasswordError(newPasswordError);

    if (!newEmailError && !newPasswordError) {
      onSubmit(email, password);
    }
  };

  const isFormValid = validateEmail(email) && validatePassword(password);

  return (
    <form onSubmit={handleSubmit} className="w-full max-w-md p-8 space-y-6 bg-white rounded-lg shadow-md">
      <h2 className="text-2xl font-semibold text-center text-gray-800">Login</h2>

      <div>
        <label htmlFor="email" className="block text-sm font-medium text-gray-700 mb-1">
          Email
        </label>
        <input
          id="email"
          type="email"
          value={email}
          onChange={handleEmailChange}
          className={`w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-accent focus:border-transparent transition-all ${
            emailError ? 'border-red-500' : 'border-gray-300'
          }`}
          placeholder="your@email.com"
        />
        {emailError && (
          <p className="mt-1 text-sm text-red-500 flex items-center">
            <span className="mr-1">❌</span>
            {emailError}
          </p>
        )}
      </div>

      <div>
        <label htmlFor="password" className="block text-sm font-medium text-gray-700 mb-1">
          Password
        </label>
        <div className="relative">
          <input
            id="password"
            type={isPasswordVisible ? 'text' : 'password'}
            value={password}
            onChange={handlePasswordChange}
            className={`w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-accent focus:border-transparent transition-all ${
              passwordError ? 'border-red-500' : 'border-gray-300'
            }`}
            placeholder="••••••••"
          />
          <button
            type="button"
            onClick={togglePasswordVisibility}
            className="absolute inset-y-0 right-0 px-3 flex items-center text-gray-500 hover:text-gray-700 transition-colors"
          >
            {isPasswordVisible ? '👁️' : '🙈'}
          </button>
        </div>
        {passwordError && (
          <p className="mt-1 text-sm text-red-500 flex items-center">
            <span className="mr-1">❌</span>
            {passwordError}
          </p>
        )}
      </div>

      <button
        type="submit"
        disabled={!isFormValid}
        className={`w-full py-3 rounded-lg font-medium transition-all ${
          isFormValid
            ? 'bg-accent text-white hover:bg-purple-600 focus:ring-accent'
            : 'bg-gray-300 text-gray-500 cursor-not-allowed'
        }`}
      >
        Login
      </button>
    </form>
  );
}
```
